package com.ayindebuild.app\n\nimport android.os.Bundle\nimport android.widget.Button\nimport android.widget.EditText\nimport android.widget.ScrollView\nimport android.widget.TextView\nimport androidx.appcompat.app.AppCompatActivity\nimport com.ayindebuild.app.services.BuildService\nimport com.ayindebuild.app.services.LLMService\n\nclass MainActivity : AppCompatActivity() {\n    private lateinit var outputView: TextView\n    private lateinit var inputField: EditText\n    private lateinit var buildService: BuildService\n    private lateinit var llmService: LLMService\n\n    override fun onCreate(savedInstanceState: Bundle?) {\n        super.onCreate(savedInstanceState)\n        setContentView(R.layout.activity_main)\n\n        outputView = findViewById(R.id.output_view)\n        inputField = findViewById(R.id.input_field)\n        \n        buildService = BuildService(this)\n        llmService = LLMService(this)\n\n        // Compile button\n        findViewById<Button>(R.id.compile_btn).setOnClickListener {\n            val command = inputField.text.toString()\n            if (command.isNotEmpty()) {\n                buildService.compile(command) { output ->\n                    runOnUiThread { outputView.append(\"\\n[BUILD]\\n\" + output) }\n                }\n            }\n        }\n\n        // Run button\n        findViewById<Button>(R.id.run_btn).setOnClickListener {\n            val command = inputField.text.toString()\n            if (command.isNotEmpty()) {\n                buildService.run(command) { output ->\n                    runOnUiThread { outputView.append(\"\\n[RUN]\\n\" + output) }\n                }\n            }\n        }\n\n        // AI Chat button\n        findViewById<Button>(R.id.ai_btn).setOnClickListener {\n            val prompt = inputField.text.toString()\n            if (prompt.isNotEmpty()) {\n                llmService.chat(prompt) { response ->\n                    runOnUiThread { outputView.append(\"\\n[AI]\\n\" + response) }\n                }\n            }\n        }\n\n        // Download Model button\n        findViewById<Button>(R.id.download_model_btn).setOnClickListener {\n            val modelName = inputField.text.toString()\n            if (modelName.isNotEmpty()) {\n                llmService.downloadModel(modelName) { progress ->\n                    runOnUiThread { outputView.append(\"\\n📥 Download: $progress%\") }\n                }\n            }\n        }\n    }\n}\n